INSERT INTO outcomes (id, topic_id, description, position) VALUES
(1, 1, 'responding to a request to collect a quantity of objects or reading a numeral and selecting the associated quantity of items from a collection to match the number required; for example, collecting 9 paint brushes after hearing the word ‘nine’', 0),
(2, 1, 'recognising the order in the sequence of numbers to 20 and identifying the number that is “one less” than a', 1),
(3, 1, 'understanding and using terms such as “first”, “second”, “third”, … “fifth”… to indicate ordinal position in a sequence; for example, creating a number track using cards with the numerals zero to 20 and describing positions using terms such as first, last, before, after, between', 2),
(4, 1, 'recognising, writing and reading numerals written on familiar objects; for example, in images, text or illustrations in story books; writing a numeral on a container as a label to show how many objects it contains', 3),
(5, 1, 'connecting quantities to number names and numerals when reading and reciting stories and playing counting games or determining and reasoning about the size of sets of objects within First Nation Australians’ instructive games; for example, Segur etug from Mer Island in the Torres Strait region', 4),
(6, 2, 'recognising how many objects are in a collection or in images on a card with a quick look and saying the associated number without counting', 0),
(7, 2, 'playing instructive card games that rely on the recognition of numbers represented in different ways; for', 1),
(8, 3, 'establishing the language and process of counting, understanding that each object must be counted only once, that the arrangement of objects does not affect how many there are, and that the last number counted answers the question of “How many?”; for example, saying numbers in sequence while playing and performing actions', 0),
(9, 3, 'using counting to compare the size of two or more collections of like items to justify which collection contains more or less items', 1),
(10, 3, 'using counting and one-to-one correspondence to quantify the number of items required for a purpose; for example, when asked to collect enough scissors for each member of their group to have a pair, counting each member and using the total count to know how many to collect', 2),
(11, 3, 'discussing how different cultures may have alternative ways of representing the count; for example, discussing how people of the Asia region use an abacus or Chinese hand gestures', 3),
(12, 3, 'using body-tallying that involves body parts and one-to-one correspondence from counting systems of First Nations Peoples of Australia, to count to 20', 4),
(13, 4, 'recognising numbers represented in physical or virtual ten-frames, and describing their reasoning: “It’s 7 because there is 5 there and 2 more”', 0),
(14, 4, 'partitioning collections of up to 10 objects in different ways and saying the part-part-whole relationship; for', 1),
(15, 4, 'representing part-part-whole relationships in numbers up to 10 using physical or virtual materials; for example, identifying numbers represented by dots in standard number configurations such as dominos and dice by recognising parts that form the whole', 2),
(16, 4, 'exploring number groupings in First Nations Australians’ counting systems and the different ways of representing these groupings to form and partition numbers, applying this to quantify collections of objects in the environment on Country/Place up to 10', 3),
(17, 5, 'using role-play and materials to represent mathematical relationships in stories; for example, “Eight kangaroos were drinking at the river and 3 hopped away”; drawing a picture and using materials to represent the situation, discussing, and recording the result of the action with a numeral', 0),
(18, 5, 'role playing or actively engaging in situations that involve quantifying or comparing collections of items or simple', 1),
(19, 5, 'representing situations expressed in First Nations Australians’ stories, such as “Tiddalick, the greedy frog”, that describe additive situations and their connections to Country/Place', 2),
(20, 5, 'representing addition and subtraction situations found in leaf games involving sets of objects used to tell stories, such as games from the Warlpiri Peoples of Yuendumu in the Northern Territory', 3),
(21, 6, 'using materials to role-play equal sharing; for example, sharing pieces of fruit or a bunch of grapes between 4 people and discussing how you would know they have been shared equally; when playing card games where each player is dealt the same number of cards, and counting the number of cards after the deal to ensure they have the same amount', 0),
(22, 6, 'representing situations that involve counting several items; for example, 9 beads or 6 \$1 coins, and sharing them equally between 3 people by subitising or counting each group by ones to decide how many beads or coins each person will receive', 1),
(23, 6, 'exploring instructive games of First Nations Australians that involve sharing; for example, playing Yangamini of the Tiwi Peoples of Bathurst Island to investigate and discuss equal sharing', 2),
(24, 7, 'recognising, copying and describing different repeating patterns using materials, shapes, sounds and movements during activities and play; for example, making a bead necklace and describing the pattern they', 0),
(25, 7, 'recognising repeating patterns used at home and in daily activities to help make tasks easier or to solve problems; for example, setting the table to eat', 1),
(26, 7, 'recognising and describing repeating patterns that can be observed on Country/Place and in First Nation Australians artwork, cultural performances and material cultures; for example, shell and seed necklaces, dances and songs', 2),
(27, 8, 'using language to describe the measurement attributes of length, mass, capacity and duration, and connecting the words with the appropriate attribute; for example, using words like “tall”, “short”, “wide”, “long”, “high” to describe the attribute of length', 0),
(28, 8, 'directly comparing pairs of objects to say which is longer/shorter, and explaining or demonstrating how they know; for example, standing back-to-back to determine who is taller; choosing to line up the bases of a spoon', 1),
(29, 8, 'starting 2 events at the same time to decide which takes longer; for example, putting on a pair of sandals with buckles or Velcro, describing the duration using familiar terms and reasoning, “I took a longer time because I’m still learning to do up my buckles”', 2),
(30, 8, 'directly comparing pairs of everyday objects from the kitchen pantry to say which is heavier/lighter; for example, hefting a tin of baked beans and a packet of marshmallows; comparing the same pair of objects to say which is longer/shorter and discussing comparisons', 3),
(31, 9, 'ordering images of daily events on a string line across the room, and justifying the placement by referring to morning, lunchtime, afternoon, and night time', 0),
(32, 9, 'distinguishing between the days of the school week and weekends, and recognising that the days of the week form a sequence that repeats, with Monday always following on from Sunday', 1),
(33, 9, 'sequencing the events from a story in the order in which they occurred using language like, “This happened first” then “This happened next”', 2),
(34, 9, 'creating, interpreting and discussing classroom rosters; for example, a roster for watering the classroom garden and asking, “Who watered the garden yesterday?” or “Whose turn is it today?”', 3),
(35, 9, 'creating a pictorial diary to show the important events that happen on the various days of the week', 4),
(36, 10, 'sorting a collection of shapes into groups based on different features such as the number of sides, colour or size, and describing how they have been sorted', 0),
(37, 10, 'creating a picture using a variety of shapes and a range of materials, including objects to trace around, describing the shapes they have created or used and sharing why they chose each shape in their picture', 1),
(38, 10, 'creating familiar shapes using groups of people; for example, holding hands and creating a circle', 2),
(39, 10, 'recognising and naming shapes that are (close to) rectangles, squares, triangles and circles in component parts of everyday items; for example, on bicycles, toy vehicles or kitchen pantry items', 3),
(40, 10, 'describing and naming shapes within objects that can be observed on Country/Place, recreating and sorting into groups based on their shape', 4),
(41, 11, 'describing the position of an item in relation to other items in the space using language like “inside”, “underneath” and “on top of”; for example, when asked “Where are the scissors kept?”, responding with “They are in abox, on the bottom shelf at the back of the classroom”', 0),
(42, 11, 'describing where they have moved themselves and items in relation to other items within a space, using familiar terms; for example, playing a hiding game and when asked “Where did you hide the ball?”, responding, “I hid it behind the garbage bin over there near the bench”', 1),
(43, 11, 'exploring First Nations Australians’ instructive games; for example, Thapumpan from the Wik-Mungkan Peoples of Cape Bedford in north Queensland, describing position and movement of self in relation to other participants, objects or locations', 2),
(44, 12, 'collecting, and sorting data collected through everyday activities or events; for example, sorting toys into categories, such as “toys that move” and “toys that don’t move”', 0),
(45, 12, 'collecting and deciding how to organise data to answer “Yes/No” questions; for example, “Do more people in our class today have shoes with laces than without?”; explaining that lining up, and matching shoes with and without', 1),
(46, 12, 'creating classroom charts and rosters using stickers to represent data; comparing and interpreting representations', 2),
(47, 12, 'investigating statistical contexts after reading a story, such as “The Waterhole” by Graeme Base; asking and responding to questions like “What different animals did you see?”, “How many different types of animals were there?” or “Were there more tigers or kangaroos?”', 3),
(48, 12, 'exploring what and how information from the environment is collected and used by First Nations Australians to predict weather events', 4),
(49, 13, 'reading, writing and naming numerals and ordering two-digit numbers from zero to at least 120, using patterns within the natural number system, including numbers that look and sound similar; for example, 16, 60, 61 and 66', 0),
(50, 13, 'using number tracks or positioning a set of numbered cards in the correct order and relative location by pegging on an empty number line', 1),
(51, 13, 'using hundreds charts to build understanding and fluency with numbers; for example, collaboratively building a hundreds chart using cards numbered from zero to 99; colour code the count of tens in a hundreds chart using one colour to represent the number of tens and another to represent the number of ones', 2),
(52, 13, 'recognising that numbers are used in all languages and cultures but may be represented differently in words and symbols; for example, through kanji numbers in Japanese and characters in Chinese, and that there are alternate numeration systems; for example, using special characters for 10 and 100 and other multiples of 10 in Japanese and Chinese numeration', 3),
(53, 14, 'building knowledge and understanding of the part-part-whole facts to 10, using physical and virtual materials; for example, using virtual ten-frames through a digital app or website to identify pairs of numbers that combine to make 10', 0),
(54, 14, 'using physical and virtual materials to partition numbers into counts of tens and ones; for example, recognise 35', 1),
(55, 14, 'using part-part-whole reasoning and physical or virtual materials to represent 24, then partitioning 24 in different ways and recording the partitions using numbers; for example, 10, 10 and 4 combine to make 24 or 10 and 14 combine to make 24', 2),
(56, 15, 'counting a large collection of items using groups of fives or tens and skip counting to work out how many there are; recording the amount and connecting the digits in the number to the grouped materials when using groups of 10', 0),
(57, 15, 'counting collections of objects such as pencils or images of birds in a tree, by grouping them in tens to enable', 1),
(58, 15, 'counting a large collection of Australian \$1 coins by stacking them into piles of 10, skip counting in tens and including any leftover coins to determine the total value', 2),
(59, 16, 'using drawings, physical and virtual materials and number combinations within 10 to add and subtract collections to 20', 0),
(60, 16, 'adding and subtracting numbers within 20, using a variety of representations and strategies such as counting', 1),
(61, 16, 'developing and using strategies for one-digit addition and subtraction based on part-part-whole relationships for each of the numbers to 10 and subitising with physical and virtual materials; for example, 8 and 6 is the same as 8 and 2 and 4', 2),
(62, 16, 'representing story problems involving addition and subtraction of numbers within 20 using a Think Board, recognising and using + and − symbols and the equal sign to represent the operations of addition and subtraction; showing and explaining the connections between any materials used using the language of plus and minus, and the numbers within the story problem', 3),
(63, 16, 'creating and performing addition and subtraction stories told through First Nations Australians’ dances', 4),
(64, 17, 'modelling problems involving addition and subtraction presented in stories, using a Think Board to represent the problem, solving the problem using physical materials and explaining the connections between any materials used, the Think Board diagram and the numbers within the story', 0),
(65, 17, 'modelling simple money problems involving addition and subtraction using whole dollar amounts; for example, setting up a shop and role-playing practical problems of buying and selling of goods, using addition and subtraction with play money and prices in whole dollar amounts; solving the problem “I had \$14 and was given \$15 for my birthday” using addition to answer the problem', 1),
(66, 17, 'modelling a variety of different additive situations to solve practical problems; for example, keeping track of the number of people on a bus as it stops to pick up and drop off passengers or the number of people entering a lift', 2),
(67, 18, 'modelling problems involving repeated equal group situations, such as, “How many wheels are needed for 3 cars?”, using materials and drawing a picture to show what they did, and recording the results with a number', 0),
(68, 18, 'modelling practical problems involving equal sharing situations; for example, sharing a set of dominoes between the 2 players in a game, and then counting or subitising to ensure they both have the same number of tiles', 1),
(69, 18, 'modelling money problems involving equal sharing; for example, sorting coins from a money box according to', 2),
(70, 19, 'using number charts, songs, rhymes and stories to establish skip counting sequences of twos, fives and tens', 0),
(71, 19, 'using shapes and objects to represent a growing pattern formed by skip counting; for example, using blocks or beads to represent the growing patterns 2, 4, 6, 8, 10 … and 5, 10, 15, 20 …', 1),
(72, 19, 'recognising the patterns in sequences formed by skip counting; for example, that skip counting in fives starting from zero always results in either a 5 or zero as the final digit', 2),
(73, 19, 'counting by twos, fives, or tens to determine how much money is in a collection of coins or notes of the same denomination; for example, 5 cent, 10 cent and \$2 coins or \$5 and \$10 notes', 3),
(74, 19, 'using different variations of the popular Korean counting game Sam-yuk-gu for generating skip counting pattern sequences', 4),
(75, 20, 'interpreting a repeating pattern sequence created by someone else, noticing and describing the repeating part of the pattern and explaining how they know what comes next in the sequence', 0),
(76, 20, 'generalising a repeating pattern by identifying the unit of repeat and representing the elements using numbers,', 1),
(77, 20, 'recognising within the sequencing of natural numbers that 0 – 9 digits are repeated both in and between the decades and using this pattern to continue the sequence and name two-digit numbers beyond 20', 2),
(78, 20, 'identifying the repeating patterns in First Nations Australians’ systems of counting, exploring different ways of representing numbers including oral and gestural language', 3),
(79, 20, 'considering how the making of shell or seed necklaces by First Nations Australians includes practices such as sorting shells and beads based on colour, size and shape, and creating a repeating pattern sequence', 4),
(80, 21, 'using a piece of string to indirectly compare the length of several objects, deciding which will fit within a space; using comparative language to describe the order: shortest, short, longer, longest', 0),
(81, 21, 'ordering the mass of 3 or more objects such as rocks, using hefting and balance scales; using comparative language to explain the order: lightest, light, heavier, heaviest, and how they decided on the order', 1),
(82, 21, 'pouring sand/rice/water from one container to another to compare and order the capacity of 3 or more containers; describing the order of the results in terms of which holds the most/least, and those in between', 2),
(83, 21, 'creating sand timers from everyday items or recycled material and comparing them to order the duration of time required for the sand to run through', 3),
(84, 21, 'investigating situations where First Nations Australians estimate, compare and communicate measurements; for example, the duration of seasons; understanding animal behaviour using the length of animal tracks; investigating capacity through water management techniques of First Nations Australians, such as traditional water carrying vessels and rock holes', 4),
(85, 22, 'using 2 different units; for example, pop sticks and pencils, to measure the length of an object such as a desk, and explaining why the number of units used may be different', 0),
(86, 22, 'comparing the length of 2 objects such as a desk and a bookshelf by laying multiple copies of a unit and', 1),
(87, 22, 'measuring the distance between 2 locations using footsteps, comparing the results and explaining why there may be different results; for example, referring to the different length of footsteps as using different units', 2),
(88, 22, 'measuring and comparing the length of objects using blocks; for example, comparing the height of 2 toys by stacking blocks one on top of the other and counting how many it takes to reach the height of each object to decide which is taller', 3),
(89, 23, 'naming, listing and using familiar units of time, such as hours, days, weeks, years,', 0),
(90, 23, 'comparing the number of days in the months of the year and explaining how the months cycle from one year to the next', 1),
(91, 23, 'sequencing familiar events including the representation of time with pictorial timelines', 2),
(92, 23, 'discussing events and activities and deciding whether they would take closer to an hour, a day, a week, a month or a year; for example, it takes a day for the sun to rise and fall and rise again, but it takes less than an hour for me to walk to school', 3),
(93, 23, 'investigating durations of time represented in First Nations Australians’ seasonal calendars', 4),
(94, 24, 'classifying a collection of shapes, including different circles, ovals, regular and irregular shapes, triangles and quadrilaterals, saying what is the same about the shapes in a group and what is different between the groups', 0),
(95, 24, 'selecting a shape from a small collection of shapes inside a bag and describing the shape by feel, so that others can name the shape and give reasons for their choice', 1),
(96, 24, 'comparing the different objects that can be built out of the same number of blocks or centi-cubes and discussing the differences between them', 2),
(97, 24, 'exploring string games used in story telling by First Nations Australians; for example, Karda from the Yandruwandha Peoples of north-east South Australia, recognising, comparing, describing and classifying the shapes made by the string and their relationship to shapes and objects on Country/Place', 3),
(98, 25, 'interpreting and following directions around familiar locations, and understanding the meaning and importance of the words when giving directions; for example, using words like “forwards” and “backwards”, “straight ahead”, “left or right” to describe movement and giving instructions like “Keep going straight until you reach the end of', 0),
(99, 25, 'creating and following an algorithm consisting of a set of instructions to move an object to a different location; for example, role-playing being a robot and following step-by-step instructions given by another classmate to move from one place to another, only moving as instructed', 1),
(100, 25, 'following directions to move people into different positions within a line using both ordinal and positional language to describe their position; for example, directly comparing heights and following directions using ordinal and positional language to line up in height order', 2),
(101, 25, 'describing a familiar journey across Country/Place using directional language', 3),
(102, 26, 'discussing methods of collecting data to answer a question, such as “What types of rubbish are found in the playground?”, sharing ideas and trying out some of the suggested methods; reviewing the data collected and explaining how they might change the way they collect data next time', 0),
(103, 26, 'collecting and recording information on a topic of interest using lists; for example, “how many people follow a', 1),
(104, 26, 'creating a tally to record data while observing events such as the year level of students using the bike shed; deciding on the possible categories before the observations are taken, then reviewing the data afterwards to notice whether the tally was effective', 2),
(105, 26, 'using star charts with stickers or emojis to represent class data; for example, using emojis on a personal feeling chart to represent how they are feeling each day or using emojis to represent activities on the class calendar', 3),
(106, 26, 'exploring ways of representing, sharing and communicating data through stories and symbols used by First Nations Australians', 4),
(107, 27, 'creating a pictograph with objects or drawings; discussing the possible categories for the pictograph, arranging the objects or drawings into the categories, then reflecting on the chosen categories and deciding whether they were helpful', 0),
(108, 27, 'translating data from a list or pictorial display into a tally chart to make counting easier; describing what the tally chart is showing, by referring to the categories; using skip counting by fives to compare the numbers within each', 1),
(109, 27, 'recognising that when there is no data for a particular category you may choose whether or not to include it in your data display, and use a zero or blank for that category depending on the purpose of the data collection or presentation; for example, creating a birthday calendar for the class and discussing that there are no students born in May and therefore there are no names listed', 2),
(110, 27, 'representing data with objects and drawings where one object or drawing represents one data value; describing the displays and explaining patterns that have been created using counting strategies to determine the frequency of responses', 3),
(111, 27, 'exploring First Nations Australian children’s instructive games; for example, Kolap from Mer Island in the Torres Strait region, recording the outcomes, representing and discussing the results', 4),
(112, 28, 'recognising missing numbers on different number lines; for example, a number line with 1800 on one end and 220 on the other, with every decade numbered', 0),
(113, 28, 'recognising and locating the position of pieces within hundreds chart puzzles using knowledge of the order of', 1),
(114, 28, 'reading and writing numerals, and saying and ordering two-, three- and four-digit numbers using patterns in the number system, including numbers with zeros in different places, and numbers that look and sound similar such as 808, 880, 818 and 881', 2),
(115, 28, 'collecting large quantities of materials for recycling; for example, ring pulls, bottle tops and bread tags, and grouping them into ones, tens and hundreds; using the materials to show different representations of two- and three-digit numbers', 3),
(116, 29, 'comparing the digits of a number with materials grouped into hundreds, tens and ones, and explaining the meaning of each of the digits in the materials', 0),
(117, 29, 'renaming numbers in different ways using knowledge of place value; for example, renaming 245 as 24 tens and 5 ones or 2 hundreds and 45 ones', 1),
(118, 30, 'creating halves of a range of collections sets by sharing collections into 2 equal groups; for example, comparing half of a set of 12 washers with half of a set of 8 bolts to identify how they both represent one-half of their respective set', 0),
(119, 30, 'creating halves using measurement attributes; for example, explaining that “a half is one part out of 2 equal', 1),
(120, 30, 'using repeated halving to subdivide shapes and objects in different ways to make corresponding halves, quarters and eighths; naming the parts and comparing the size of them to notice that they are all the same size, and demonstrating that a quarter is a half of a half and that an eighth is a half of a quarter', 2),
(121, 30, 'dividing a shape into equal parts and relating the number of parts to the unit fraction; for example, if there are 4 equal parts then each part is a one-quarter and if there are 8 equal parts then each is one-eighth', 3),
(122, 31, 'using the associative property of addition to assist with mental calculation by partitioning, rearranging and regrouping numbers using number knowledge, near doubles and bridging to 10 strategies; for example, calculating 7 + 8 using 7 + (7 + 1) = (7 + 7) + 1, the associative property and near doubles; calculating 7 + 8 using the associative property and bridging to 10 7 + (3 + 5) = (7 + 3) + 5', 0),
(123, 31, 'using strategies such as doubles, near doubles, part-part-whole knowledge to 10, bridging tens and partitioning', 1),
(124, 31, 'representing addition and subtraction problems using a bar model and writing a number sentence, explaining how each number in the sentence is connected to the situation', 2),
